  return {contentVersion:Number(g.contentVersion)||1,cases:(Array.isArray(g.cases)?g.cases:[]).slice(0,10).map(c=>({name:str(c.name,100),passed:c.passed===true,inputs:str(c.inputs,4000),actual:str(c.actual),expected:str(c.expected,4000),message:str(c.message,4000)})),verdict:g.verdict,summary:str(g.summary,1000),expected:str(g.expected,1000),at:str(g.at,50),ok:g.ok===true,stdout:str(g.stdout),stderr:str(g.stderr),error:str(g.error,1000),explanation:str(g.explanation,2000),exitCode:Number.isInteger(g.exitCode)?g.exitCode:null,elapsedMs:Math.max(0,Number(g.elapsedMs)||0)};
