 const statusText=s=>({knowledge_pass:'Đã làm đạt',read:'Đã đọc',solid:'Tự làm + chuyển giao',independent:'Đã tự làm (cũ)',ai_pass:'AI xác nhận đạt',python_pass:'Python: đạt kết quả',python_retry:'Python: cần sửa',api_pass:'API: đạt kết quả',api_retry:'API: cần sửa',sql_pass:'SQL: đạt kết quả',skipped:'Đã bỏ qua',practice:'Đang luyện',new:'Chưa đánh giá'}[s]);
 function draft(id){if(!state.drafts[id])state.drafts[id]={code:'',output:'',notes:'',question:'',hints:0,solution:false,mode:'standard',checks:[]};return state.drafts[id];}
 function dueLessons(){return C.lessons.filter(l=>{const a=attemptsFor(l.id).filter(x=>x.assessment!=='skipped');if(!a.length)return false;const last=a[a.length-1];const n=a.filter(x=>['independent','ai_pass','sql_pass','python_pass','api_pass'].includes(x.assessment)).length;const days=['independent','ai_pass','sql_pass','python_pass','api_pass'].includes(last.assessment)?[1,3,7,14][Math.min(Math.max(n-1,0),3)]:1;return Date.now()-Date.parse(last.at)>=days*86400000;});}
